// update-comments.js
// Role: Refresh the header comment date on each changed build script.
// Last reviewed: 2026-11-27

const fs = require('fs');
const path = require('path');
const { execFileSync } = require('child_process');

const root = path.resolve(__dirname, '..');

// Reminder: docs.js is generated by generate-docs.js. Never add a hand-written header to it.
const scripts = [
  'build/app.js',
  'build/ask-onboarding.js',
  'build/check-contradictions.js',
  'build/check-docs.js',
  'build/discover-mcp.js',
  'build/free-locks.js',
  'build/generate-docs.js',
  'build/gates/check-data-rules.js',
  'build/gates/check-free-locks.js',
  'build/mcp-lib.js',
  'build/one-shot.js',
  'build/smoke-test.js',
  'build/update-comments.js',
  'build/update-roadmap.js'
];

// A script header is a title line, an optional Title line, a Role line, and a review date.
const headerPattern = /^\/\/ ([^\n]+)\n((?:\/\/ [A-Z][^\n]*\n)*)\/\/ Role: ([^\n]+)\n\/\/ Last reviewed: (\d{4}-\d{2}-\d{2})\n/;

function today() {
  const now = new Date();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  return String(now.getFullYear()) + '-' + month + '-' + day;
}

function isChanged(relative) {
  const status = execFileSync('git', ['status', '--porcelain', '--', relative], {
    cwd: root,
    encoding: 'utf8'
  });
  return status.trim().length > 0;
}

let failures = 0;
let updates = 0;

for (const relative of scripts) {
  const filePath = path.join(root, relative);

  if (!fs.existsSync(filePath)) {
    console.log('FAIL: missing build script ' + relative);
    failures += 1;
    continue;
  }

  const text = fs.readFileSync(filePath, 'utf8');
  const match = headerPattern.exec(text);

  if (!match) {
    console.log('FAIL: ' + relative + ' needs a title line, a Role line, and a Last reviewed date at the top');
    failures += 1;
    continue;
  }

  const title = match[1].trim();
  const extra = match[2];
  const role = match[3].trim();

  if (title !== path.basename(relative)) {
    console.log('FAIL: ' + relative + ' header title must be ' + path.basename(relative));
    failures += 1;
  }
  if (!role.endsWith('.') || role.length > 100) {
    console.log('FAIL: ' + relative + ' Role line must be one short sentence that ends with a period');
    failures += 1;
  }

  if (!isChanged(relative)) {
    continue;
  }

  const date = today();
  if (date === match[4]) {
    continue;
  }

  const header = '// ' + title + '\n' + extra + '// Role: ' + role + '\n// Last reviewed: ' + date + '\n';
  fs.writeFileSync(filePath, header + text.slice(match[0].length), 'utf8');
  console.log('UPDATE: ' + relative + ' Last reviewed ' + match[4] + ' -> ' + date);
  updates += 1;
}

if (failures > 0) {
  console.log('FAIL: code comment review found ' + failures + ' problem(s)');
  process.exit(1);
}

console.log('PASS: code comment review of ' + scripts.length + ' scripts with ' + updates + ' date(s) refreshed');
